=head2 Google::Cloud::Alloydb::V1alpha::Service::GenerateClientCertificateRequest

Message for requests to generate a client certificate signed by the Cluster
CA.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. The name of the parent resource. The required format is:
 * projects/{project}/locations/{location}/clusters/{cluster}

=item * C<< $msg->request_id() >> / C<< $msg->request_id($value) >>

Type: C<String>

Optional. An optional request ID to identify requests. Specify a unique
request ID so that if you must retry your request, the server ignores the
request if it has already been completed. The server guarantees that for at
least 60 minutes since the first request.

For example, consider a situation where you make an initial request and
the request times out. If you make the request again with the same request
ID, the server can check if the original operation with the same request ID
was received, and if so, ignores the second request. This prevents
clients from accidentally creating duplicate commitments.

The request ID must be a valid UUID with the exception that zero UUID is
not supported (00000000-0000-0000-0000-000000000000).

=item * C<< $msg->pem_csr() >> / C<< $msg->pem_csr($value) >>

Type: C<String>

Optional. A pem-encoded X.509 certificate signing request (CSR). It is
recommended to use public_key instead.

=item * C<< $msg->cert_duration() >> / C<< $msg->cert_duration($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

Optional. An optional hint to the endpoint to generate the client
certificate with the requested duration. The duration can be from 1 hour to
24 hours. The endpoint may or may not honor the hint. If the hint is left
unspecified or is not honored, then the endpoint will pick an appropriate
default duration.

=item * C<< $msg->public_key() >> / C<< $msg->public_key($value) >>

Type: C<String>

Optional. The public key from the client.

=item * C<< $msg->use_metadata_exchange() >> / C<< $msg->use_metadata_exchange($value) >>

Type: C<Bool>

Optional. An optional hint to the endpoint to generate a client certificate
that can be used by AlloyDB connectors to exchange additional metadata with
the server after TLS handshake.

=back

=head2 Google::Cloud::Alloydb::V1alpha::Service::GenerateClientCertificateResponse

Message returned by a GenerateClientCertificate operation.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->pem_certificate() >> / C<< $msg->pem_certificate($value) >>

Type: C<String>

Output only. The pem-encoded, signed X.509 certificate.

=item * C<< $msg->pem_certificate_chain() >> / C<< $msg->pem_certificate_chain($value) >>

Type: C<String>

Output only. The pem-encoded chain that may be used to verify the X.509
certificate. Expected to be in issuer-to-root order according to RFC 5246.

=item * C<< $msg->ca_cert() >> / C<< $msg->ca_cert($value) >>

Type: C<String>

Optional. The pem-encoded cluster ca X.509 certificate.

=back

